'use client'

import * as React from 'react'
import {
  cn,
  tagsInputConnect,
  tagsInputMachine,
  type TagsInputProps as CoreTagsInputProps,
  type TagsInputApi,
  type TagsInputValueChangeDetails,
} from "@/lib/utils"
import { normalizeProps, useMachine } from '@zag-js/react'
import { XIcon } from 'lucide-react'

export interface TagsInputProps extends Omit<CoreTagsInputProps, 'id' | 'onValueChange'> {
  id?: CoreTagsInputProps['id']
  onValueChange?: (details: TagsInputValueChangeDetails) => void
  children?: React.ReactNode
  className?: string
}

const TagsInputContext = React.createContext<TagsInputApi | null>(null)

export const useTagsInput = (): TagsInputApi => {
  const context = React.useContext(TagsInputContext)
  if (!context) {
    throw new Error('useTagsInput must be used within a TagsInputProvider')
  }
  return context
}

export function TagsInput({
  defaultValue,
  value,
  onValueChange,
  className,
  children,
  ...props
}: TagsInputProps) {
  const service = useMachine(tagsInputMachine, {
    id: React.useId(),
    value: value ?? defaultValue,
    onValueChange,
    ...props,
  })

  const api = tagsInputConnect(service, normalizeProps)

  return (
    <TagsInputContext.Provider value={api}>
      <div {...api.getRootProps()} className={cn('flex flex-col gap-2', className)}>
        {children}
      </div>
    </TagsInputContext.Provider>
  )
}

export function TagsInputControl({ className, children, ...props }: React.ComponentProps<'div'>) {
  const api = useTagsInput()
  return (
    <div
      {...api.getControlProps()}
      className={cn(
        'flex flex-wrap gap-2 rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-sm placeholder:text-muted-foreground focus-within:outline-none focus-within:ring-1 focus-within:ring-ring disabled:cursor-not-allowed disabled:opacity-50',
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

export function TagsInputInput({ className, ...props }: React.ComponentProps<'input'>) {
  const api = useTagsInput()
  return (
    <input
      {...api.getInputProps()}
      className={cn(
        'flex-1 bg-transparent outline-none placeholder:text-muted-foreground',
        className
      )}
      {...props}
    />
  )
}

export function TagsInputItem({
  index,
  value,
  className,
  children,
}: {
  index: string | number
  value: string
  className?: string
  children?: React.ReactNode
}) {
  const api = useTagsInput()
  const itemState = api.getItemState({ index, value })

  return (
    <div
      {...api.getItemProps({ index, value })}
      className={cn(
        'inline-flex items-center gap-1 rounded bg-secondary px-2 py-1 text-sm font-medium text-secondary-foreground hover:bg-secondary/80',
        itemState.highlighted ? 'ring-2 ring-ring ring-offset-2' : '',
        className
      )}
    >
      <span className="leading-none">{value}</span>
      <button
        {...api.getItemDeleteTriggerProps({ index, value })}
        className="ml-1 rounded-full outline-none hover:bg-background/20 focus:ring-2 focus:ring-ring focus:ring-offset-1"
      >
        <XIcon className="h-3 w-3" />
      </button>
      <input {...api.getItemInputProps({ index, value })} />
    </div>
  )
}

export function TagsInputClearTrigger({
  className,
  children,
  ...props
}: React.ComponentProps<'button'>) {
  const api = useTagsInput()
  return (
    <button
      {...api.getClearTriggerProps()}
      className={cn('text-sm text-muted-foreground hover:text-foreground', className)}
      {...props}
    >
      {children || 'Clear'}
    </button>
  )
}

import { type ComputedRef, inject, provide } from 'vue'
import type { TagsInputApi } from "@/lib/utils"

export const TagsInputContextKey = Symbol('TagsInputContext')

export function provideTagsInputContext(api: ComputedRef<TagsInputApi>) {
    provide(TagsInputContextKey, api)
}

export function useTagsInputContext(): ComputedRef<TagsInputApi> {
    const context = inject<ComputedRef<TagsInputApi>>(TagsInputContextKey)
    if (!context) {
        throw new Error('useTagsInputContext must be used within a TagsInputProvider')
    }
    return context
}

import { setupTagsInputMachine } from './use-tags-input'

type WeappTagsInputApi = {
  addValue?: (value: string) => void
  deleteValue?: (index: number) => void
}

type WeappService = {
  setContext: (context: Record<string, object>) => void
}

type InputEvent = WechatMiniprogram.CustomEvent<{
  value: string
}>

type DeleteTagEvent = WechatMiniprogram.BaseEvent & {
  currentTarget: {
    dataset: {
      index?: number
    }
  }
}

type WeappTagsInputInternal = WechatMiniprogram.Component.InstanceMethods<WechatMiniprogram.IAnyObject> & {
  _service?: WeappService
  _cleanup?: () => void
  _send?: (event: object) => void
  data: {
    api: WeappTagsInputApi
    inputValue: string
  }
  properties: {
    value: string[]
    max: number
    disabled: boolean
    readOnly: boolean
    allowOverflow: boolean
    placeholder: string
    id: string
    extClass: string
  }
}

Component({
  options: {
    styleIsolation: 'apply-shared',
    pureDataPattern: /^_/,
  },

  properties: {
    value: { type: Array, value: [] },
    max: { type: Number, value: Number.MAX_SAFE_INTEGER },
    disabled: { type: Boolean, value: false },
    readOnly: { type: Boolean, value: false },
    allowOverflow: { type: Boolean, value: false },
    placeholder: { type: String, value: '添加标签...' },
    id: { type: String, value: 'tags-input' },
    extClass: { type: String, value: '' },
  },

  data: {
    api: {} as WeappTagsInputApi,
    className: '',
    inputValue: '',
  },

  lifetimes: {
    attached() {
      const self = this as WeappTagsInputInternal
      const { service, cleanup, send } = setupTagsInputMachine(this, {
        id: this.properties.id,
        value: this.properties.value,
        max: this.properties.max,
        disabled: this.properties.disabled,
        readOnly: this.properties.readOnly,
        allowOverflow: this.properties.allowOverflow,
        onValueChange: (details) => {
          this.triggerEvent('change', details)
        }
      })

      self._service = service as WeappService
      self._cleanup = cleanup
      self._send = send as (event: object) => void
    },
    detached() {
      const self = this as WeappTagsInputInternal
      self._cleanup?.()
    },
  },

  observers: {
    'state': function (state) {
      const self = this as WeappTagsInputInternal
      if (!state || !self._send) return
      const { connect } = setupTagsInputMachine(this, { id: this.properties.id })
      const api = connect(state, self._send) as WeappTagsInputApi
      this.setData({ api, className: this.properties.extClass })
    },
  },

  methods: {
    onInput(e: InputEvent) {
      this.setData({ inputValue: e.detail.value })
    },
    onConfirm(e: InputEvent) {
      const self = this as WeappTagsInputInternal
      const value = e.detail.value.trim()
      if (value && self.data.api.addValue) {
        self.data.api.addValue(value)
        this.setData({ inputValue: '' })
      }
    },
    onDeleteTag(e: DeleteTagEvent) {
      const self = this as WeappTagsInputInternal
      const index = e.currentTarget.dataset.index
      if (typeof index === 'number') {
        self.data.api.deleteValue?.(index)
      }
    },
  },
})
